-- 第二阶段：基础资料与排课；在 0001 后执行。
CREATE TABLE students(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,name TEXT NOT NULL,gender TEXT NOT NULL DEFAULT '',birth_year INTEGER,school TEXT NOT NULL DEFAULT '',grade TEXT NOT NULL DEFAULT '',direction TEXT NOT NULL DEFAULT '',phone_enc TEXT,parent_name TEXT NOT NULL DEFAULT '',parent_phone_enc TEXT,status TEXT NOT NULL DEFAULT 'active',notes TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id));
CREATE TABLE teachers(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,name TEXT NOT NULL,phone_enc TEXT,subjects TEXT NOT NULL DEFAULT '[]',employment TEXT NOT NULL DEFAULT 'part_time',status TEXT NOT NULL DEFAULT 'active',sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id));
CREATE TABLE course_categories(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,name TEXT NOT NULL,color TEXT NOT NULL DEFAULT '#8B7BB5',active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id));
CREATE TABLE course_types(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,name TEXT NOT NULL,category_id TEXT NOT NULL,format TEXT NOT NULL DEFAULT 'individual',default_minutes INTEGER NOT NULL DEFAULT 45,units_per_lesson REAL NOT NULL DEFAULT 1,capacity INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,category_id) REFERENCES course_categories(tenant_id,id));
CREATE TABLE locations(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,name TEXT NOT NULL,campus TEXT NOT NULL DEFAULT '',offsite INTEGER NOT NULL DEFAULT 0,capacity INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id));
CREATE TABLE student_schedule_blocks(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,weekday INTEGER NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,label TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE schedule_templates(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,teacher_id TEXT NOT NULL,assistant_id TEXT,course_type_id TEXT NOT NULL,location_id TEXT,weekday INTEGER NOT NULL,start_time TEXT NOT NULL,duration INTEGER NOT NULL,units REAL NOT NULL,mode TEXT NOT NULL DEFAULT 'offline',date_from TEXT NOT NULL,date_to TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,teacher_id) REFERENCES teachers(tenant_id,id), FOREIGN KEY(tenant_id,assistant_id) REFERENCES teachers(tenant_id,id), FOREIGN KEY(tenant_id,course_type_id) REFERENCES course_types(tenant_id,id), FOREIGN KEY(tenant_id,location_id) REFERENCES locations(tenant_id,id));
CREATE TABLE schedule_enrollments(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,template_id TEXT NOT NULL,student_id TEXT NOT NULL,date_from TEXT NOT NULL,date_to TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,template_id) REFERENCES schedule_templates(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE lessons(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,start_at TEXT NOT NULL,duration INTEGER NOT NULL,units REAL NOT NULL,teacher_id TEXT NOT NULL,assistant_id TEXT,course_type_id TEXT NOT NULL,location_id TEXT,mode TEXT NOT NULL DEFAULT 'offline',status TEXT NOT NULL DEFAULT 'planned',template_id TEXT,occurrence_date TEXT,note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,teacher_id) REFERENCES teachers(tenant_id,id), FOREIGN KEY(tenant_id,assistant_id) REFERENCES teachers(tenant_id,id), FOREIGN KEY(tenant_id,course_type_id) REFERENCES course_types(tenant_id,id), FOREIGN KEY(tenant_id,location_id) REFERENCES locations(tenant_id,id), FOREIGN KEY(tenant_id,template_id) REFERENCES schedule_templates(tenant_id,id));
CREATE TABLE lesson_participants(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,lesson_id TEXT NOT NULL,student_id TEXT NOT NULL,attendance TEXT NOT NULL DEFAULT 'planned',deducted REAL NOT NULL DEFAULT 0,package_id TEXT,makeup_for TEXT,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,lesson_id) REFERENCES lessons(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id), FOREIGN KEY(tenant_id,package_id) REFERENCES packages(tenant_id,id));
CREATE TABLE packages(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,course_type_id TEXT NOT NULL,units_total REAL NOT NULL DEFAULT 0,valid_from TEXT,valid_to TEXT,status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id), FOREIGN KEY(tenant_id,course_type_id) REFERENCES course_types(tenant_id,id));
CREATE UNIQUE INDEX lesson_occurrence ON lessons(tenant_id,template_id,occurrence_date) WHERE template_id IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX lesson_student ON lesson_participants(tenant_id,lesson_id,student_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX template_student_period ON schedule_enrollments(tenant_id,template_id,student_id,date_from) WHERE deleted_at IS NULL;
CREATE INDEX lesson_dates ON lessons(tenant_id,start_at);
CREATE INDEX block_student ON student_schedule_blocks(tenant_id,student_id);
CREATE UNIQUE INDEX user_teacher ON users(tenant_id,teacher_id) WHERE teacher_id IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX user_student ON users(tenant_id,student_id) WHERE student_id IS NOT NULL AND deleted_at IS NULL;
CREATE TABLE tenant_data_versions(tenant_id TEXT PRIMARY KEY REFERENCES tenants(id),version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE mutation_guards(tenant_id TEXT NOT NULL,id TEXT NOT NULL,expected INTEGER NOT NULL,actual INTEGER NOT NULL,CHECK(expected=actual),PRIMARY KEY(tenant_id,id));
CREATE TRIGGER user_teacher_reference BEFORE INSERT ON users WHEN NEW.teacher_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM teachers WHERE tenant_id=NEW.tenant_id AND id=NEW.teacher_id AND status='active' AND deleted_at IS NULL) THEN RAISE(ABORT,'invalid_teacher_reference') END; END;
CREATE TRIGGER user_student_reference BEFORE INSERT ON users WHEN NEW.student_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM students WHERE tenant_id=NEW.tenant_id AND id=NEW.student_id AND status='active' AND deleted_at IS NULL) THEN RAISE(ABORT,'invalid_student_reference') END; END;
CREATE TRIGGER teacher_archive_accounts AFTER UPDATE OF status,deleted_at ON teachers WHEN NEW.status<>'active' OR NEW.deleted_at IS NOT NULL BEGIN UPDATE users SET active=0,version=version+1 WHERE tenant_id=NEW.tenant_id AND teacher_id=NEW.id; END;
CREATE TRIGGER student_archive_accounts AFTER UPDATE OF status,deleted_at ON students WHEN NEW.status<>'active' OR NEW.deleted_at IS NOT NULL BEGIN UPDATE users SET active=0,version=version+1 WHERE tenant_id=NEW.tenant_id AND student_id=NEW.id; END;
CREATE TRIGGER user_teacher_active BEFORE UPDATE OF active ON users WHEN NEW.active=1 AND NEW.teacher_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM teachers WHERE tenant_id=NEW.tenant_id AND id=NEW.teacher_id AND status='active' AND deleted_at IS NULL) THEN RAISE(ABORT,'invalid_teacher_reference') END; END;
CREATE TRIGGER user_student_active BEFORE UPDATE OF active ON users WHEN NEW.active=1 AND NEW.student_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM students WHERE tenant_id=NEW.tenant_id AND id=NEW.student_id AND status='active' AND deleted_at IS NULL) THEN RAISE(ABORT,'invalid_student_reference') END; END;
CREATE TRIGGER student_delete_link BEFORE UPDATE OF deleted_at ON students WHEN NEW.deleted_at IS NOT NULL AND EXISTS(SELECT 1 FROM users WHERE tenant_id=NEW.tenant_id AND student_id=NEW.id AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'profile_in_use'); END;
CREATE TRIGGER teacher_delete_link BEFORE UPDATE OF deleted_at ON teachers WHEN NEW.deleted_at IS NOT NULL AND EXISTS(SELECT 1 FROM users WHERE tenant_id=NEW.tenant_id AND teacher_id=NEW.id AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'profile_in_use'); END;
